# ---------------------------------------------------------------- S86
S(86, 'Risk and the purpose of insurance', 'Identify risk management strategies and explain how insurance transfers financial risk',
  main=[
    q('Luis pays a company $40 a month so that if his phone is stolen, the company pays for a replacement. Which risk strategy is this?', 'Transferring the risk',
      [('Avoiding the risk by never owning a phone at all', 'Avoiding means not doing the risky thing'), ('Reducing the risk by using a stronger case', 'Reducing lowers the chance or size of a loss'), ('Keeping the risk and paying for losses himself', 'Retaining means bearing the loss')],
      intro='Four ways to manage risk: avoid it (do not do the risky thing), reduce it (make a loss less likely or smaller), retain it (pay for losses yourself), or transfer it (pay someone else, usually an insurer, to take the loss). Insurance is risk transfer.',
      fb='Insurance moves the cost of a loss to the insurer in exchange for a premium.', sub='Risk strategies'),
    q('In insurance, what does the word "premium" mean?', 'The price paid for coverage',
      [('The money the insurer pays after a covered loss', 'Confuses premium with a claim payment'), ('The part of a loss the policyholder pays first', 'Confuses premium with a deductible'), ('A bonus paid to drivers with no accidents', 'Invents a payment')],
      intro='Key terms: the premium is what you pay for coverage (monthly or yearly). A claim is your request for payment after a loss. The deductible is the part of a covered loss you pay before the insurer pays.',
      fb='The premium is the cost of the policy.', sub='Premium'),
    q('A covered loss costs $3,000. Luis\'s deductible is $500. How much does the insurer pay?', '$2,500',
      [('$3,000', 'Ignores the deductible'), ('$500', 'Gives the deductible'), ('$3,500', 'Adds the deductible')],
      intro='For most property losses, the policyholder pays the deductible and the insurer pays the rest, up to the policy limit.',
      fb='$3,000 − $500 = $2,500.', calc=2500, sub='Deductible'),
    q('How can insurers afford to pay large losses?', 'Many people\'s premiums pool together',
      [('The government refunds every claim the insurer pays', 'Invents a subsidy'), ('Insurers only sell to people who never have losses', 'Ignores how risk works'), ('Policyholders repay the claim later with interest', 'Confuses insurance with a loan')],
      intro='Insurance pools risk: many people each pay a small, predictable premium, and the pool pays the few who have large losses.',
      fb='Pooling many premiums covers the few large losses.', sub='Risk pooling'),
    q('Which loss is most sensible to retain (pay yourself) rather than insure?', 'A $15 phone charger that breaks',
      [('A house fire that destroys everything you own', 'A catastrophic loss; insure it'), ('A crash that injures another driver badly', 'A huge liability; insure it'), ('A long illness with large hospital bills', 'A huge cost; insure it')],
      intro='Insurance matters most for losses that are unlikely but too large to afford. Small, affordable losses are often cheaper to retain, especially with an emergency fund.',
      fb='Retain small losses; insure the ones that could be financially devastating.', sub='What to insure'),
  ],
  back=[
    concept('Risk, probability, and loss', 'Insurance decisions compare how likely a loss is with how large it would be.', [
      q('Which word describes a chance of losing money or something of value?', 'Risk',
        [('Equity', 'Value owned'), ('Liquidity', 'Ease of using money'), ('Principal', 'An amount borrowed or invested')],
        fb='Risk is the chance of loss.', sub='Risk'),
      q('Wearing a seat belt is which risk strategy?', 'Reducing the risk',
        [('Transferring the risk to another person', 'No one else takes the loss'), ('Avoiding the risk entirely', 'You still ride in the car'), ('Retaining the risk on purpose', 'You are actively making the loss smaller')],
        intro='Reducing risk makes a loss less likely or less severe, such as seat belts, smoke alarms, or locks.',
        fb='Seat belts make injuries less severe: risk reduction.', sub='Reducing risk'),
      q('An event has a 1 in 50 chance of happening each year. What is that as a percent?', '2%',
        [('50%', 'Uses the denominator'), ('0.02%', 'Leaves it as a decimal and adds a percent sign'), ('20%', 'Misplaces the decimal')],
        fb='1 ÷ 50 = 0.02 = 2%.', calc=2, sub='Probability as a percent'),
      q('Which situation is risk avoidance?', 'Choosing not to ride a motorcycle',
        [('Buying a helmet before riding', 'Reduction'), ('Buying motorcycle insurance before riding', 'Transfer'), ('Saving to pay for any damage', 'Retention')],
        fb='Not doing the activity avoids its risk.', sub='Avoiding risk'),
      q('Why does an emergency fund help with risk?', 'It covers small losses and deductibles',
        [('It replaces the need for any insurance at all', 'Cannot cover catastrophic losses'), ('It lowers the chance an accident happens', 'Money does not change the odds'), ('It earns enough to pay any lawsuit', 'Overstates its size')],
        fb='Cash on hand lets you retain small losses and pay deductibles.', sub='Retaining risk'),
    ]),
    math('Understand probability as a number from 0 to 1', 'Risk is described with probabilities.', 'grade_7', 54),
  ],
  go=[
    deeper('Reading a policy', [
      q('A renters policy has a $20,000 limit for personal property. A fire destroys $26,000 of belongings, and the deductible is $500. How much does the insurer pay?', '$20,000',
        [('$25,500', 'Ignores the policy limit'), ('$26,000', 'Ignores the limit and the deductible'), ('$19,500', 'Subtracts the deductible from the limit')],
        intro='A policy limit is the most an insurer will pay for a covered loss. The deductible is subtracted from the loss first; the insurer then pays the result, but never more than the limit.',
        fb='$26,000 − $500 = $25,500, capped at the $20,000 limit.', calc=20000, sub='Policy limits'),
      q('A policy lists "Exclusions: flood, earthquake." What does that mean?', 'Those losses are not covered',
        [('Those losses are covered with no deductible', 'Reverses the meaning'), ('Those losses are covered only on weekends', 'Invents a condition'), ('Those losses are paid at double the limit', 'Invents a benefit')],
        intro='Exclusions list what a policy does not cover. Flood insurance, for example, is usually a separate policy.',
        fb='Excluded losses are not covered.', sub='Exclusions', how=True),
      q('What is the declarations page of a policy?', 'A summary of coverage, limits, and premium',
        [('A letter saying a claim was denied', 'Confuses with a denial letter'), ('A form to cancel the policy', 'Confuses with a cancellation form'), ('A list of every claim you have filed', 'Confuses with a claims history')],
        intro='The declarations ("dec") page shows who and what is covered, the limits, deductibles, and the premium.',
        fb='The dec page summarizes the policy.', sub='Declarations page', how=True),
      q('Replacement cost coverage pays to buy a new item; actual cash value pays the item\'s value minus depreciation. A 4-year-old TV cost $800 and is now worth $300. Under actual cash value, before any deductible, what is paid?', '$300',
        [('$800', 'Describes replacement cost'), ('$500', 'Gives the depreciation'), ('$1,100', 'Adds the amounts')],
        intro='Replacement cost policies cost more but pay enough to replace items new.',
        fb='Actual cash value pays the depreciated value, $300.', calc=300, sub='Replacement vs actual cash value'),
      q('After a covered loss, what is a sound first step in filing a claim?', 'Document the damage with photos',
        [('Throw away damaged items before anyone sees them', 'Destroys evidence'), ('Wait a year to see if more damage appears', 'Claims have deadlines'), ('Exaggerate the loss to cover the deductible', 'Insurance fraud')],
        intro='Contact the insurer promptly, take photos, keep receipts, and prevent further damage.',
        fb='Photos and receipts support a claim.', sub='Filing a claim', how=True),
    ]),
  ],
  nat=('Managing Risk', 'Explain risk management strategies and how insurance pools and transfers risk'), nj=['RM'],
  sources=[NAIC], extra=['Reading a declarations page', 'Filing a claim'])

