    q('What does homeowners insurance usually cover that renters insurance does not?', 'The building itself',
      [('Personal belongings such as a laptop', 'Both can cover belongings'), ('Liability if a guest is hurt', 'Both include liability'), ('Living costs after a covered loss', 'Both can include this')],
      intro='Renters insurance covers belongings and liability; the landlord insures the building. Homeowners insurance also covers the structure. Lenders require it for a mortgage.',
      fb='Homeowners insurance adds coverage for the dwelling.', sub='Homeowners vs renters'),
